    <style>
        /* --- Alap stílusok és dinamikus változók --- */
        @import url('');

        :root {
            /* These colors are set instantly by JS on load */
            --primary: #990c58;
            --secondary: #e51284;
            --accent: #e51284;
            --border-glow: rgba(229, 18, 132, 0.5);

            /* Static variables */
            --bg: #000000;
            --surface: rgba(5, 5, 5, 0.9);
            --glass: rgba(255, 255, 255, 0.08);
            --glass-strong: rgba(255, 255, 255, 0.15);
            --border: rgba(255, 255, 255, 0.2);
            --text: #ffffff;
            --text-muted: #cccccc;
            --radius: 12px;
            --shadow: 0 8px 32px rgba(0, 0, 0, 0.5);
            --transition-curve: cubic-bezier(0.25, 0.8, 0.25, 1);
        }

        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
            -webkit-tap-highlight-color: transparent;
        }

        html {
            height: 100%;
            height: -webkit-fill-available;
            scroll-behavior: smooth;
            -webkit-overflow-scrolling: touch;
        }

        body {
            font-family: 'Inter', sans-serif;
            background: var(--bg);
            color: var(--text);
            min-height: 100vh;
            min-height: -webkit-fill-available;
            overflow-x: hidden;
            -webkit-font-smoothing: antialiased;
            -moz-osx-font-smoothing: grayscale;
        }

        @supports (padding: max(0px)) {
            body {
                padding-left: max(0px, env(safe-area-inset-left));
                padding-right: max(0px, env(safe-area-inset-right));
            }
        }

        ::-webkit-scrollbar {
            width: 4px;
        }

        ::-webkit-scrollbar-track {
            background: transparent;
        }

        ::-webkit-scrollbar-thumb {
            background: var(--glass-strong);
            border-radius: 10px;
            border: 1px solid var(--border);
        }

        /* --- Szuper lassú, folyékony "liquid" háttér --- */
        .aurora-background {
            position: fixed;
            top: 0;
            left: 0;
            width: 100vw;
            height: 100vh;
            pointer-events: none;
            z-index: -1;
            overflow: hidden;
        }

        .aurora-background .aurora {
            position: absolute;
            border-radius: 30% 70% 70% 30% / 30% 30% 70% 70%;
            mix-blend-mode: multiply;
            filter: blur(100px);
            opacity: 0.4;
            transition: background-color 15s linear;
            transform-origin: center center;
        }

        .aurora.one {
            width: 85vw;
            height: 60vw;
            animation: move-one 1200s linear infinite, fluid-morph-one 45s ease-in-out infinite;
            opacity: 0.32;
        }

        .aurora.two {
            width: 75vw;
            height: 90vw;
            animation: move-two 1050s linear infinite, fluid-morph-two 55s ease-in-out infinite;
            opacity: 0.29;
        }

        @keyframes move-one {
            0% {
                transform: translate(-40vw, -30vh);
            }

            25% {
                transform: translate(90vw, 10vh) scale(1.1);
            }

            50% {
                transform: translate(120vw, 90vh) scale(0.9);
            }

            75% {
                transform: translate(-10vw, 120vh) scale(1.0);
            }

            100% {
                transform: translate(-40vw, -30vh);
            }
        }

        @keyframes move-two {
            0% {
                transform: translate(110vw, 110vh);
            }

            25% {
                transform: translate(-20vw, 80vh) scale(0.8);
            }

            50% {
                transform: translate(-50vw, 10vh) scale(1.2);
            }

            75% {
                transform: translate(20vw, -30vh) scale(1.0);
            }

            100% {
                transform: translate(110vw, 110vh);
            }
        }

        @keyframes move-three {
            0% {
                transform: translate(50vw, 120vh);
            }

            25% {
                transform: translate(100vw, 40vh) scale(1.1);
            }

            50% {
                transform: translate(20vw, -30vh) scale(0.8);
            }

            75% {
                transform: translate(-20vw, 70vh) scale(1.2);
            }

            100% {
                transform: translate(50vw, 120vh);
            }
        }

        @keyframes move-four {
            0% {
                transform: translate(-30vw, 50vh);
            }

            25% {
                transform: translate(30vw, 110vh) scale(1.2);
            }

            50% {
                transform: translate(110vw, 20vh) scale(0.9);
            }

            75% {
                transform: translate(40vw, -10vh) scale(1.1);
            }

            100% {
                transform: translate(-30vw, 50vh);
            }
        }

        @keyframes fluid-morph-one {
            0% {
                border-radius: 30% 70% 70% 30% / 30% 30% 70% 70%;
                transform: rotate(0deg) scaleX(1) scaleY(1);
            }
            25% {
                border-radius: 60% 40% 30% 70% / 60% 30% 70% 40%;
                transform: rotate(90deg) scaleX(1.2) scaleY(0.8);
            }
            50% {
                border-radius: 40% 60% 60% 40% / 70% 60% 40% 30%;
                transform: rotate(180deg) scaleX(0.9) scaleY(1.3);
            }
            75% {
                border-radius: 70% 30% 40% 60% / 40% 70% 30% 60%;
                transform: rotate(270deg) scaleX(1.1) scaleY(0.7);
            }
            100% {
                border-radius: 30% 70% 70% 30% / 30% 30% 70% 70%;
                transform: rotate(360deg) scaleX(1) scaleY(1);
            }
        }

        @keyframes fluid-morph-two {
            0% {
                border-radius: 60% 40% 30% 70% / 40% 60% 70% 30%;
                transform: rotate(0deg) scaleX(1) scaleY(1);
            }
            20% {
                border-radius: 30% 70% 60% 40% / 70% 30% 40% 60%;
                transform: rotate(72deg) scaleX(0.8) scaleY(1.4);
            }
            40% {
                border-radius: 70% 30% 40% 60% / 30% 70% 60% 40%;
                transform: rotate(144deg) scaleX(1.3) scaleY(0.6);
            }
            60% {
                border-radius: 40% 60% 70% 30% / 60% 40% 30% 70%;
                transform: rotate(216deg) scaleX(0.9) scaleY(1.2);
            }
            80% {
                border-radius: 50% 50% 50% 50% / 80% 20% 80% 20%;
                transform: rotate(288deg) scaleX(1.1) scaleY(0.9);
            }
            100% {
                border-radius: 60% 40% 30% 70% / 40% 60% 70% 30%;
                transform: rotate(360deg) scaleX(1) scaleY(1);
            }
        }


        /* --- Fő elrendezés --- */
        .container {
            display: flex;
            min-height: 100vh;
            min-height: -webkit-fill-available;
            position: relative;
        }

        /* --- Dinamikusan Színezett Elemek --- */
        .logo-icon,
        .user-bubble {
            background: linear-gradient(135deg, var(--primary), var(--secondary));
            transition: background 30s ease-in-out;
        }

        .logo-text h1,
        .welcome-title,
        .modal-title {
            background: linear-gradient(135deg, var(--primary), var(--secondary));
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            transition: background 30s ease-in-out;
        }

        /* Aurora háttér színek harmonizálása */
        .aurora.one,
        .aurora.two {
            transition: background-color 30s ease-in-out;
        }

        .header-title {
            background: linear-gradient(135deg, var(--primary), var(--secondary));
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            text-shadow: 0 0 20px var(--border-glow);
            transition: background 30s ease-in-out, text-shadow 10s linear;
        }

        .send-btn,
        .modal-submit-btn,
        .ai-action-btn,
        .start-btn {
            background-color: var(--accent);
            border-color: var(--accent);
            transition: all 0.3s var(--transition-curve), background-color 30s ease-in-out, border-color 10s linear;
        }

        .category-title i,
        .service-icon,
        .stat-number,
        .document-icon,
        .document-arrow,
        .document-section h3,
        .synthesis-content {
            color: var(--accent);
            transition: color 30s ease-in-out;
        }

        .document-preview,
        .document-section h3,
        .synthesis-content {
            border-color: var(--accent);
            transition: border-color 30s ease-in-out, background-color 0.3s ease, transform 0.3s ease;
        }

        .typing-dot {
            background-color: var(--primary);
            transition: background-color 30s ease-in-out;
        }

        .research-indicator .spinner {
            border-top-color: var(--accent);
            transition: border-top-color 30s ease-in-out;
        }

        .service-item:hover {
            border-left-color: var(--primary);
        }

        .progress-fill {
            background: linear-gradient(90deg, var(--primary), var(--secondary));
        }

        /* --- Oldalsáv (Sidebar) --- */
        .sidebar {
            width: 260px;
            background: var(--surface);
            backdrop-filter: blur(40px) saturate(180%);
            border-right: 1px solid var(--border);
            overflow-y: auto;
            position: fixed;
            height: 100vh;
            height: -webkit-fill-available;
            z-index: 1000;
            transform: translateX(-100%);
            transition: transform 0.4s var(--transition-curve);
            display: flex;
            flex-direction: column;
        }

        .sidebar.open {
            transform: translateX(0);
        }

        .sidebar-overlay {
            position: fixed;
            top: 0;
            left: 0;
            width: 100vw;
            height: 100vh;
            background: rgba(0, 0, 0, 0.5);
            backdrop-filter: blur(10px);
            z-index: 999;
            opacity: 0;
            visibility: hidden;
            transition: all 0.4s ease;
        }

        .sidebar-overlay.active {
            opacity: 1;
            visibility: visible;
        }

        .sidebar-header {
            padding: 16px 12px;
            border-bottom: 1px solid var(--border);
        }

        .logo {
            display: flex;
            align-items: center;
            gap: 8px;
            margin-bottom: 16px;
        }

        .logo-icon {
            width: 32px;
            height: 32px;
            border-radius: 8px;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 1.2rem;
            font-weight: 800;
            color: #fff;
            box-shadow: 0 4px 15px rgba(0, 0, 0, 0.3);
            transition-property: transform, background;
        }

        .logo:hover .logo-icon {
            transform: rotate(-10deg) scale(1.1);
        }

        .logo-text h1 {
            font-size: 1.2rem;
